package vip.xiaonuo.srm.sourcing;
import java.util.*;
import java.math.*;
import java.time.*;
import cn.hutool.crypto.digest.DigestUtil;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import vip.xiaonuo.common.exception.CommonException;
import vip.xiaonuo.srm.api.SrmSupplierAccessApi.Context;
import static vip.xiaonuo.srm.sourcing.SourcingInputs.*;
import static vip.xiaonuo.srm.sourcing.SourcingRules.*;
import static vip.xiaonuo.srm.sourcing.SourcingStore.*;
@Service @RequiredArgsConstructor @Transactional(isolation=Isolation.READ_COMMITTED)
public class SourcingRfqService {
 private final SourcingStore x;
 private void validate(Context a,Rfq p,String rid){
  x.writer(a);require(p.deadline()>x.now()&&p.deadline()<=x.now()+366L*86400000,400,"截止时间须在未来一年内");require(p.startAt()==null||p.startAt()<p.deadline(),400,"开始时间须早于截止时间");require(new HashSet<>(p.supplierIds()).size()==p.supplierIds().size(),400,"邀请名单不能重复");require(new HashSet<>(p.lines().stream().map(Line::id).toList()).size()==p.lines().size(),400,"物料行编号不能重复");
  require(x.db.queryForObject("SELECT COUNT(*) FROM SRM_CATEGORY WHERE CODE=? AND ENABLED=true",Long.class,p.category())==1,400,"物料品类不存在或已停用");
  for(String sid:p.supplierIds().stream().sorted().toList()){x.qualified(a,sid,a.orgId(),true);require(x.access.requireSupplier(a,sid,false).category().equals(p.category()),400,"邀请须匹配供应商品类");}
  for(var line:p.lines())for(String fid:line.fileIds())require(rid!=null&&x.db.queryForObject("SELECT COUNT(*) FROM SRM_SRC_FILE WHERE ID=? AND RFQ_ID=? AND ORG_ID=?",Long.class,fid,rid,a.orgId())==1,403,"规格附件不属于当前询价");
  if(p.strategy().equals("AUCTION")){long start=cents(p.startingPrice()),step=cents(p.minDecrement());require(step<start,400,"最小降幅须小于起始总价");}
 }
 private Map<String,Object> cfg(Rfq p){var c=new LinkedHashMap<String,Object>();c.put("lines",p.lines());c.put("startingPrice",p.startingPrice());c.put("minDecrement",p.minDecrement());c.put("antiSnipeMinutes",p.antiSnipeMinutes()==null?5:p.antiSnipeMinutes());return c;}
 private void invites(String rid,List<String> ids){x.db.update("DELETE FROM SRM_SRC_INVITE WHERE RFQ_ID=?",rid);int i=0;for(String sid:ids)x.db.update("INSERT INTO SRM_SRC_INVITE VALUES(?,?,?)",rid,sid,"供方-"+String.format("%03d",++i));}
 public Map<String,Object> create(Context a,Rfq p){x.writer(a);String hash=DigestUtil.sha256Hex(x.json(p));var prior=x.db.queryForList("SELECT * FROM SRM_SRC_RFQ WHERE ORG_ID=? AND REQUEST_KEY=?",a.orgId(),p.requestKey());if(!prior.isEmpty()){var old=prior.get(0);require(hash.equals(old.get("REQUEST_HASH"))&&a.userId().equals(old.get("CREATED_BY")),409,"创建请求键已用于其他内容");return detail(a,s(old,"ID"));}validate(a,p,null);String rid=id();
  try{x.db.update("INSERT INTO SRM_SRC_RFQ(ID,ORG_ID,RFQ_NO,TITLE,CATEGORY,STRATEGY,CURRENCY,STATUS,DEADLINE_MS,START_MS,CONFIG_CIPHER,ROW_VERSION,LAST_TIME_MS,CREATED_BY,CREATED_AT,REQUEST_KEY,REQUEST_HASH) VALUES(?,?,?,?,?,?,?,'DRAFT',?,?,?,0,?,?,NOW(3),?,?)",rid,a.orgId(),p.rfqNo()==null||p.rfqNo().isBlank()?"RFQ"+rid:p.rfqNo(),p.title(),p.category(),p.strategy(),p.currency(),p.deadline(),p.startAt()==null?0:p.startAt(),x.crypto.encrypt(x.json(cfg(p))),x.now(),a.userId(),p.requestKey(),hash);}catch(org.springframework.dao.DuplicateKeyException e){throw new CommonException(409,"询价编号或请求键已存在");}
  invites(rid,p.supplierIds());x.auditRfq(a,x.trusted(rid,false),"RFQ_CREATED",Map.of("lineCount",p.lines().size()));return detail(a,rid);
 }
 public Map<String,Object> edit(Context a,String rid,Rfq p){validate(a,p,rid);var r=x.rfq(a,rid,true);x.version(r,p.rowVersion());require(s(r,"STATUS").equals("DRAFT"),409,"发布后核心物料和邀请不能修改");require(s(r,"ORG_ID").equals(a.orgId()),403,"只能维护当前组织询价");
  var edited=cfg(p);if(!x.access.canViewUnitPrice(a)){var oldLines=new HashMap<String,Map<String,Object>>();for(var line:x.lines(r))oldLines.put(String.valueOf(line.get("id")),line);var preserved=new ArrayList<Map<String,Object>>();for(var input:p.lines()){var line=x.object(x.json(input));if(input.benchmark()==null&&oldLines.containsKey(input.id()))line.put("benchmark",oldLines.get(input.id()).get("benchmark"));preserved.add(line);}edited.put("lines",preserved);}
  x.db.update("UPDATE SRM_SRC_RFQ SET TITLE=?,CATEGORY=?,STRATEGY=?,CURRENCY=?,DEADLINE_MS=?,START_MS=?,CONFIG_CIPHER=?,ROW_VERSION=ROW_VERSION+1 WHERE ID=?",p.title(),p.category(),p.strategy(),p.currency(),p.deadline(),p.startAt()==null?0:p.startAt(),x.crypto.encrypt(x.json(edited)),rid);invites(rid,p.supplierIds());x.auditRfq(a,r,"RFQ_DRAFT_EDITED",Map.of("version",p.rowVersion()+1));return detail(a,rid);
 }
 public Map<String,Object> publish(Context a,String rid,Version p){x.writer(a);var first=x.rfq(a,rid,false);for(String sid:x.invited(rid))x.qualified(a,sid,s(first,"ORG_ID"),true);var r=x.rfq(a,rid,true);x.version(r,p.rowVersion());require(s(r,"STATUS").equals("DRAFT")&&n(r,"DEADLINE_MS")>x.now(),409,"仅未截止草稿可发布");var cfg=x.config(r);var weights=x.performance.weightsFor(YearMonth.now(ZoneId.of("Asia/Shanghai")));cfg.put("weights",weights.weights());cfg.put("weightVersion",weights.version());
  long start=Math.max(x.now(),n(r,"START_MS"));require(start<n(r,"DEADLINE_MS"),400,"开始时间须早于截止时间");x.db.update("UPDATE SRM_SRC_RFQ SET STATUS='PUBLISHED',CONFIG_CIPHER=?,START_MS=?,LAST_TIME_MS=?,ROW_VERSION=ROW_VERSION+1 WHERE ID=?",x.crypto.encrypt(x.json(cfg)),start,x.now(),rid);x.notifyAll(rid,"INVITATION","收到询价邀请："+s(r,"TITLE"));x.auditRfq(a,r,"RFQ_PUBLISHED",Map.of("weightVersion",weights.version()));x.event(rid);return detail(a,rid);
 }
 public Map<String,Object> extend(Context a,String rid,Extend p){x.writer(a);var r=x.rfq(a,rid,true);x.version(r,p.rowVersion());require(s(r,"STATUS").equals("PUBLISHED")&&p.deadline()>n(r,"DEADLINE_MS")&&p.deadline()>x.now()&&p.deadline()<=x.now()+366L*86400000,409,"只能延长未封盘询价且新截止时间须更晚");x.db.update("UPDATE SRM_SRC_RFQ SET DEADLINE_MS=?,ROW_VERSION=ROW_VERSION+1 WHERE ID=?",p.deadline(),rid);x.notifyAll(rid,"EXTENDED","询价已延期："+s(r,"TITLE"));x.auditRfq(a,r,"RFQ_EXTENDED",Map.of("deadline",p.deadline()));x.event(rid);return detail(a,rid);}
 public Map<String,Object> withdraw(Context a,String rid,Version p){x.writer(a);var r=x.rfq(a,rid,true);x.version(r,p.rowVersion());require(Set.of("DRAFT","PUBLISHED").contains(s(r,"STATUS")),409,"当前状态不能撤回");require(x.db.queryForObject("SELECT (SELECT COUNT(*) FROM SRM_SRC_QUOTE WHERE RFQ_ID=?)+(SELECT COUNT(*) FROM SRM_SRC_BID WHERE RFQ_ID=?)",Long.class,rid,rid)==0,409,"已有报价或出价，不能撤回");x.db.update("UPDATE SRM_SRC_RFQ SET STATUS='WITHDRAWN',ROW_VERSION=ROW_VERSION+1 WHERE ID=?",rid);if(s(r,"STATUS").equals("PUBLISHED"))x.notifyAll(rid,"WITHDRAWN","询价已撤回："+s(r,"TITLE"));x.auditRfq(a,r,"RFQ_WITHDRAWN",Map.of());x.event(rid);return detail(a,rid);}
 public Map<String,Object> page(Context a,int current,int size,String search){x.readable(a);require(current>=1&&current<=100000&&size>=1&&size<=100,400,"分页范围错误");var args=new ArrayList<Object>();String w;
  if(a.portal()){w="r.ORG_ID=? AND r.STATUS<>'DRAFT' AND EXISTS(SELECT 1 FROM SRM_SRC_INVITE i WHERE i.RFQ_ID=r.ID AND i.SUPPLIER_ID=? AND EXISTS(SELECT 1 FROM SRM_SRC_NOTICE pn WHERE pn.RFQ_ID=i.RFQ_ID AND pn.SUPPLIER_ID=i.SUPPLIER_ID AND pn.KIND='INVITATION'))";args.add(a.orgId());args.add(a.supplierId());}else if(a.allOrganizations())w="1=1";else if(a.ownOnly()){w="r.ORG_ID=? AND r.CREATED_BY=?";args.add(a.orgId());args.add(a.userId());}else{w=a.organizationIds().isEmpty()?"1=0":"r.ORG_ID IN ("+String.join(",",Collections.nCopies(a.organizationIds().size(),"?"))+")";args.addAll(a.organizationIds());}
  if(!search.isBlank()){w+=" AND (r.TITLE LIKE ? OR r.RFQ_NO LIKE ?)";args.add("%"+search+"%");args.add("%"+search+"%");}long total=x.db.queryForObject("SELECT COUNT(*) FROM SRM_SRC_RFQ r WHERE "+w,Long.class,args.toArray());args.add(size);args.add((current-1)*size);var rows=x.db.queryForList("SELECT r.* FROM SRM_SRC_RFQ r WHERE "+w+" ORDER BY r.CREATED_AT DESC,r.ID DESC LIMIT ? OFFSET ?",args.toArray());return Map.of("records",rows.stream().map(this::summary).toList(),"total",total,"current",current,"size",size);
 }
 Map<String,Object> summary(Map<String,Object> r){var out=new LinkedHashMap<String,Object>();for(String[] f:new String[][]{{"id","ID"},{"rfqNo","RFQ_NO"},{"title","TITLE"},{"category","CATEGORY"},{"strategy","STRATEGY"},{"currency","CURRENCY"},{"status","STATUS"},{"deadline","DEADLINE_MS"},{"startAt","START_MS"},{"rowVersion","ROW_VERSION"}})out.put(f[0],r.get(f[1]));return out;}
 public Map<String,Object> detail(Context a,String rid){var r=x.rfq(a,rid,false);var out=summary(r);var cfg=x.config(r);boolean price=a.portal()||x.access.canViewUnitPrice(a);var lines=new ArrayList<Map<String,Object>>();for(var line:x.lines(r)){var item=new LinkedHashMap<>(line);if(!price)item.remove("benchmark");lines.add(item);}out.put("lines",lines);out.put("canViewUnitPrice",price);out.put("canWrite",!a.portal()&&!Collections.disjoint(a.roles(),Set.of("SRC-SPE","CAT-MGR","superAdmin")));out.put("createdBy",a.portal()?"":r.get("CREATED_BY"));
  for(String key:List.of("startingPrice","minDecrement","antiSnipeMinutes","weights","weightVersion"))out.put(key,cfg.get(key));
  if(!a.portal())out.put("invites",x.db.queryForList("SELECT i.SUPPLIER_ID AS supplierId,i.ALIAS AS alias,s.NAME AS supplierName FROM SRM_SRC_INVITE i JOIN SRM_SUPPLIER s ON s.ID=i.SUPPLIER_ID WHERE i.RFQ_ID=? ORDER BY i.ALIAS",rid));
  out.put("files",x.db.queryForList("SELECT ID AS id,FILE_NAME AS name,MIME AS mime FROM SRM_SRC_FILE WHERE RFQ_ID=?",rid));return out;
 }
 public List<Map<String,Object>> candidates(Context a,String category,String search){x.writer(a);return x.db.queryForList("SELECT ID AS id,NAME AS name,CATEGORY AS category FROM SRM_SUPPLIER WHERE ORG_ID=? AND STATUS='QUALIFIED' AND DELETE_FLAG='NOT_DELETE' AND CATEGORY=? AND (NAME LIKE ? OR SUPPLIER_CODE LIKE ?) ORDER BY NAME LIMIT 100",a.orgId(),category,"%"+search+"%","%"+search+"%").stream().filter(r->{try{x.access.requireSupplier(a,String.valueOf(r.get("id")),false);return true;}catch(CommonException e){return false;}}).toList();}
 public Map<String,Object> quote(Context a,String rid,Quote p){x.bidder(a);x.access.requireSupplier(a,a.supplierId(),true);var r=x.rfq(a,rid,true);String hash=DigestUtil.sha256Hex(x.json(p));var prior=x.db.queryForList("SELECT ID FROM SRM_SRC_QUOTE WHERE RFQ_ID=? AND SUPPLIER_ID=? AND REQUEST_KEY=?",rid,a.supplierId(),p.requestKey());if(!prior.isEmpty()){var old=x.db.queryForMap("SELECT REQUEST_HASH FROM SRM_SRC_QUOTE WHERE ID=?",prior.get(0).get("ID"));require(hash.equals(old.get("REQUEST_HASH")),409,"报价请求键内容冲突");return quoteDetail(a,rid,String.valueOf(prior.get(0).get("ID")));}
  x.eligibility.requireEligibleForNewBusiness(a.supplierId(),s(r,"ORG_ID"));require(s(r,"STRATEGY").equals("COMPARE")&&s(r,"STATUS").equals("PUBLISHED")&&x.now()<n(r,"DEADLINE_MS"),409,"当前询价不接受报价");long round=x.db.queryForObject("SELECT COALESCE(MAX(ROUND_NO),0) FROM SRM_SRC_QUOTE WHERE RFQ_ID=? AND SUPPLIER_ID=?",Long.class,rid,a.supplierId());require(round==p.expectedRound(),409,"报价轮次已变化，请刷新");var lines=x.lines(r);var submitted=new HashMap<String,QuoteLine>();for(var line:p.lines())require(submitted.put(line.lineId(),line)==null,400,"报价物料行重复");require(submitted.size()==lines.size(),400,"报价必须覆盖全部物料行");var units=new ArrayList<BigDecimal>();var quantities=new ArrayList<BigDecimal>();for(var line:lines){var q=submitted.get(String.valueOf(line.get("id")));require(q!=null,400,"报价物料行不属于当前RFQ");units.add(q.unitPrice());quantities.add(x.decimal(line.get("quantity")));}BigDecimal total=total(units,quantities,p.freight());String qid=id();x.db.update("INSERT INTO SRM_SRC_QUOTE VALUES(?,?,?,?,?,?,?,?,?,NOW(3))",qid,rid,a.supplierId(),round+1,x.crypto.encrypt(x.json(p)),x.crypto.encrypt(total.toPlainString()),p.requestKey(),hash,a.userId());x.audit(a,r,a.supplierId(),qid,"QUOTE_SUBMITTED",Map.of("round",round+1,"requestHash",hash));return quoteDetail(a,rid,qid);
 }
 public Map<String,Object> quoteDetail(Context a,String rid,String qid){x.rfq(a,rid,false);var rows=x.db.queryForList("SELECT q.*,s.NAME AS SUPPLIER_NAME FROM SRM_SRC_QUOTE q JOIN SRM_SUPPLIER s ON s.ID=q.SUPPLIER_ID WHERE q.ID=? AND q.RFQ_ID=?",qid,rid);require(rows.size()==1&&(!a.portal()||a.supplierId().equals(rows.get(0).get("SUPPLIER_ID"))),404,"报价不存在或无权访问");var q=rows.get(0);var out=new LinkedHashMap<String,Object>();out.put("id",qid);out.put("round",q.get("ROUND_NO"));out.put("supplierId",q.get("SUPPLIER_ID"));out.put("supplierName",q.get("SUPPLIER_NAME"));out.put("total",x.crypto.decrypt(s(q,"TOTAL_CIPHER")));var payload=x.object(x.crypto.decrypt(s(q,"PAYLOAD_CIPHER")));if(!a.portal()&&!x.access.canViewUnitPrice(a)){for(var line:(List<Map<String,Object>>)payload.get("lines"))line.remove("unitPrice");}out.put("payload",payload);out.put("createdAt",q.get("CREATED_AT"));return out;}
 public List<Map<String,Object>> quotes(Context a,String rid){x.rfq(a,rid,false);String w=a.portal()?" AND SUPPLIER_ID=?":"";var args=new ArrayList<Object>();args.add(rid);if(a.portal())args.add(a.supplierId());return x.db.queryForList("SELECT ID FROM SRM_SRC_QUOTE WHERE RFQ_ID=?"+w+" ORDER BY CREATED_AT DESC,ROUND_NO DESC",String.class,args.toArray()).stream().map(id->quoteDetail(a,rid,id)).toList();}
 public Map<String,Object> question(Context a,String rid,Question p){var r=x.rfq(a,rid,true);require(Set.of("PUBLISHED","CLOSED").contains(s(r,"STATUS")),409,"当前询价不接受答疑");String sid=a.portal()?a.supplierId():p.supplierId();if(a.portal())require(p.supplierId()==null||p.supplierId().equals(a.supplierId()),403,"不能以其他供应商身份提问");else x.writer(a);if(!p.isPublic())require(sid!=null&&x.invited(rid).contains(sid),400,"私聊须选择受邀供应商");String qid=id();x.db.update("INSERT INTO SRM_SRC_QUESTION(ID,RFQ_ID,SUPPLIER_ID,IS_PUBLIC,QUESTION,CREATED_BY,CREATED_AT) VALUES(?,?,?,?,?,?,NOW(3))",qid,rid,sid,p.isPublic(),p.question(),a.userId());if(p.isPublic())x.notifyAll(rid,"QUESTION","询价有新的公开答疑");else x.notice(rid,sid,"QUESTION","询价有新的私聊答疑");x.audit(a,r,sid==null?x.invited(rid).get(0):sid,qid,"QUESTION_CREATED",Map.of("public",p.isPublic()));return Map.of("id",qid);}
 public void answer(Context a,String rid,String qid,Answer p){x.writer(a);var r=x.rfq(a,rid,true);var rows=x.db.queryForList("SELECT * FROM SRM_SRC_QUESTION WHERE ID=? AND RFQ_ID=? FOR UPDATE",qid,rid);require(rows.size()==1,404,"问题不存在");require(rows.get(0).get("ANSWER")==null,409,"回答已发布，不能静默覆盖");x.db.update("UPDATE SRM_SRC_QUESTION SET ANSWER=?,ANSWERED_BY=?,ANSWERED_AT=NOW(3) WHERE ID=?",p.answer(),a.userId(),qid);if(Boolean.TRUE.equals(rows.get(0).get("IS_PUBLIC")))x.notifyAll(rid,"ANSWER","询价公开问题已回复");else x.notice(rid,s(rows.get(0),"SUPPLIER_ID"),"ANSWER","询价私聊问题已回复");x.auditRfq(a,r,"QUESTION_ANSWERED",Map.of("questionId",qid));}
 public List<Map<String,Object>> questions(Context a,String rid){x.rfq(a,rid,false);String w=a.portal()?" AND (IS_PUBLIC=true OR SUPPLIER_ID=?)":"";var args=new ArrayList<Object>();args.add(rid);if(a.portal())args.add(a.supplierId());return x.db.queryForList("SELECT ID AS id,IS_PUBLIC AS isPublic,QUESTION AS question,ANSWER AS answer,CREATED_AT AS createdAt,SUPPLIER_ID AS supplierId FROM SRM_SRC_QUESTION WHERE RFQ_ID=?"+w+" ORDER BY CREATED_AT,ID",args.toArray()).stream().map(r->{if(a.portal())r.remove("supplierId");return r;}).toList();}
 public List<Map<String,Object>> notices(Context a){x.readable(a);if(!a.portal())return List.of();return x.db.queryForList("SELECT n.ID AS id,n.RFQ_ID AS rfqId,n.KIND AS kind,n.MESSAGE AS message,n.CREATED_AT AS createdAt FROM SRM_SRC_NOTICE n JOIN SRM_SRC_RFQ r ON r.ID=n.RFQ_ID WHERE r.ORG_ID=? AND n.SUPPLIER_ID=? AND EXISTS(SELECT 1 FROM SRM_SRC_NOTICE pn WHERE pn.RFQ_ID=r.ID AND pn.SUPPLIER_ID=n.SUPPLIER_ID AND pn.KIND='INVITATION') ORDER BY n.CREATED_AT DESC,n.ID DESC LIMIT 100",a.orgId(),a.supplierId());}
 public Map<String,Object> risk(Context a,String sid){x.readable(a);require(!a.portal(),403,"风险评估仅内部可查");return x.risk(a,sid);}
 public void risk(Context a,String sid,Risk p){require(!a.portal()&&!Collections.disjoint(a.roles(),Set.of("SQE","CAT-MGR","superAdmin")),403,"仅SQE或采购经理可登记人工风险");var s=x.access.requireSupplier(a,sid,true);String risk=id();x.db.update("INSERT INTO SRM_SRC_RISK VALUES(?,?,?,?,?,?,?,NOW(3))",risk,sid,s.orgId(),p.level(),p.evidenceRef(),p.note(),a.userId());x.access.recordEvent(a,sid,risk,"SOURCING_RISK_ASSESSED",Map.of("level",p.level(),"source","MANUAL"));}
}
